<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\ClientIdentity\Application\Usecase\Update;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\ClientIdentityRef;
use Civi\Lughauth\Features\Access\ClientIdentity\Application\Service\Visibility\ClientIdentityVisibilityService;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\Gateway\ClientIdentityWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class ClientIdentityUpdateUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly ClientIdentityVisibilityService $visibility,
        private readonly ClientIdentityWriteGateway $writer,
    ) {
    }

    public function allowUpdate(?ClientIdentityRef $ref = null): Allow
    {
        $this->logDebug("Check allow update usecase for Client identity");
        $span = $this->startSpan("Check allow update usecase for Client identity");
        try {
            $result = $this->dispatcher->dispatch(new ClientIdentityUpdateAllowDecision(Allow::allowed('update', 'Allowed to update by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function fixedFields(?ClientIdentityRef $ref = null): array
    {
        $this->logDebug("Check fixed fields for update usecase for Client identity");
        $span = $this->startSpan("Check fixed fields for update usecase for Client identity");
        try {
            return $this->visibility->fieldsToFix($ref);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function update(string $uid, ClientIdentityUpdateParams $params): ClientIdentityUpdateResult
    {
        $this->logDebug("Run update usecase for Client identity");
        $span = $this->startSpan("Run update usecase for Client identity");
        try {
            $ref = new ClientIdentityRef($uid);
            $allow = $this->allowUpdate($ref);
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to update Client identity');
            }
            if (!$original = $this->visibility->retrieveVisibleForUpdate($ref)) {
                throw new NotFoundException($uid);
            }
            $this->dispatcher->dispatch(new ClientIdentityUpdateCheck($params, $original));
            $enriched = $this->dispatcher->dispatch(new ClientIdentityUpdateEnrich($params, $original, $params->toAttributes()));
            $attributes = $enriched->getResult();
            $input = $this->visibility->copyWithFixed($attributes);
            $modified = $original->update($input);
            $result = $this->writer->update($original, $modified);
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new ClientIdentityUpdateResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
